/section><section class="grid items-stretch gap-6 lg:grid-cols-2">@foreach($lab->steps as $step)<article class="flex min-h-[520px] flex-col rounded-xl bg-white p-5 shadow-sm"><header class="flex items-center justify-between border-b border-[#D7EAFF] pb-3"><div class="flex items-center gap-2"><h2 class="text-lg font-bold">SQL Editor</h2><span class="rounded-full bg-[#0B2345]/10 px-2.5 py-0.5 font-mono text-xs font-semibold">Langkah {{ $loop->iteration }}</span></div><button type="button" data-copy-query class="rounded-lg bg-[#E2EFFF] px-3 py-1.5 text-xs font-semibold text-[#44474E]">⌘ Copy</button></header><div class="flex gap-2 overflow-x-auto py-3">@foreach(['SELECT','FROM','WHERE','JOIN','ORDER BY','GROUP BY','LIMIT'] as $symbol)<button type="button" data-sql-symbol="{{ $symbol }}" class="h-10 shrink-0 rounded-lg bg-[#E2EFFF] px-3 font-mono text-sm">{{ $symbol }}</button>@endforeach</div><p class="mb-3 text-sm leading-6 text-[#44474E]">{{ $step->instruction }}</p><div class="flex flex-1 rounded-lg bg-[#ECF4FF] p-3"><div class="select-none pr-3 text-right font-mono text-[15px] leading-6 text-[#44474E]/40">@for($line=1;$line<=8;$line++)<div>{{ $line }}</div>@endfor</div><textarea aria-label="SQL query langkah {{ $loop->iteration }}" data-query-key="radix-lab-{{ $lab->id }}-step-{{ $step->id }}" rows="8" class="min-w-0 flex-1 resize-none bg-transparent font-mono text-[15px] leading-6 text-[#000D25] outline-none" placeholder="Tulis query SQL...">{{ $step->reference_query }}</textarea></div><div data-result-panel aria-live="polite" class="mt-3 hidden max-h-40 overflow-auto rounded-lg bg-[#F7F9FF] p-3 font-mono text-xs text-[#44474E]"></div>@if(session('draft_saved') == $step->id)<div class="mt-2 rounded-lg bg-teal-50 p-2 text-xs font-semibold text-teal-800">Jawaban tersimpan. Cek pesan hasil di atas.</div>@endif<div class="flex items-center justify-between gap-3 border-t border-[#D7EAFF] pt-3">@php($lastAttempt = $attempts->get($step->id))<span data-step-status class="text-xs font-semibold {{ $lastAttempt?->is_correct ? 'text-[#006B59]' : ($lastAttempt ? 'text-red-700' : 'text-[#031D30]') }}">{{ $lastAttempt?->is_correct ? 'Benar' : ($lastAttempt ? 'Belum sesuai' : 'Belum dijalankan') }}</span><div class="flex gap-2"><button type="button" data-run-lab class="rounded-xl bg-[#0B2345] px-6 py-3 text-sm font-semibold text-white">▶ Run</button><form method="post" action="{{ route('sql-lab.attempts.store', [$lab, $step]) }}">@csrf<input type="hidden" name="query_text" data-submit-query><input type="hidden" name="result_json" value="{}"><button type="submit" class="rounded-xl bg-[#69FAD8] px-4 py-3 text-sm font-semibold text-[#002019]">Submit</button></form></div></div><div data-result-panel class="mt-3 hidden max-h-40 overflow-auto rounded-lg bg-[#F7F9FF] p-3 font-mono text-xs text-[#44474E]" role="status"></div></article>@endforeach
<section class="grid min-h-[260px] rounded-xl bg-white p-5 shadow-sm"><header class="flex items-center justify-between border-b border-[#D7EAFF] pb-3"><h2 class="text-lg font-bold">Hasil Query</h2><span class="text-xs text-[#44474E]">Output soal aktif</span></header><div data-global-result aria-live="polite" class="mt-4 min-h-[160px] overflow-auto rounded-lg bg-[#F7F9FF] p-4 font-mono text-sm text-[#44474E]"><p>Belum ada query yang dijalankan.</p></div></section><div class="flex justify-end"><img class="h-14 w-14 rounded-full bg-white object-contain shadow-sm" src="{{ asset('images/assets/avatar.png') }}" alt="Radi"></div></div></main><x-student-nav />
<script>document.querySelectorAll('[data-query-key]').forEach((editor)=>{const article=editor.closest('article');const key=editor.dataset.queryKey;editor.value=localStorage.getItem(key)||editor.value;article.querySelector('[data-copy-query]').addEventListener('click',async()=>{await navigator.clipboard.writeText(editor.value)});article.querySelectorAll('[data-sql-symbol]').forEach(button=>button.addEventListener('click',()=>{const start=editor.selectionStart;editor.value=editor.value.slice(0,start)+button.dataset.sqlSymbol+editor.value.slice(editor.selectionEnd);editor.focus();editor.selectionStart=editor.selectionEnd=start+button.dataset.sqlSymbol.length}));editor.addEventListener('input',()=>localStorage.setItem(key,editor.value));article.querySelector('[data-submit-query]').form.addEventListener('submit',()=>article.querySelector('[data-submit-query]').value=editor.value);article.querySelector('[data-run-lab]').addEventListener('click',async()=>{const panel=article.querySelector('[data-result-panel]');const output=document.querySelector('[data-global-result]');panel.classList.remove('hidden');panel.textContent='Menjalankan SQL.js...';try{const SQL=await window.RadixSQL;if(!SQL)throw new Error('SQL.js gagal dimuat. Muat ulang halaman atau nonaktifkan cache offline.');const db=new SQL.Database();const schema=@json($lab->schema_json??[]);(schema.tables||[]).forEach((table)=>{const columns=table.columns||[];db.run(`CREATE TABLE ${table.name} (${columns.map((column)=>`${column.name} ${column.type||'TEXT'}`).join(', ')})`);(table.rows||[]).forEach((row)=>db.run(`INSERT INTO ${table.name} VALUES (${row.map(()=>'?').join(',')})`,row))});const results=db.exec(editor.value);const result=results.length?{columns:results[0].columns,rows:results[0].values}: {columns:[],rows:[]};const text=results.length?results[0].values.map((row)=>row.join(' | ')).join('\n'):'Query berhasil, tidak mengembalikan baris.';article.querySelector('input[name="result_json"]').value=JSON.stringify(result);panel.textContent=text;const summary=document.createElement('section');summary.className='mb-4 rounded-lg border border-[#D7EAFF] bg-white p-3';summary.innerHTML=`<strong>Langkah ${article.querySelector('[data-submit-query]').closest('form').querySelector('input[name=query_text]')?.value ? '' : ''}</strong>`;const heading=article.querySelector('h2')?.textContent||'Soal';summary.innerHTML=`<strong>${heading}</strong><pre class="mt-2 whitespace-pre-wrap">${text.replaceAll('&','&amp;').replaceAll('<','&lt;')}</pre>`;output.querySelector('p')?.remove();output.prepend(summary);article.querySelector('[data-step-status]').textContent='Sudah dijalankan · Submit untuk cek';article.querySelector('[data-step-status]').className='text-xs font-semibold text-[#006B59]';}catch(error){panel.textContent=`Error: ${error.message}`;output.textContent=panel.textContent;article.querySelector('[data-step-status]').textContent='Query error';article.querySelector('[data-step-status]').className='text-xs font-semibold text-red-700'}});editor.addEventListener('keydown',(event)=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter')article.querySelector('[data-run-lab]').click()})});</script></body></html>